149	/// Parse one file's source into symbols and unattributed references.
150	pub(crate) fn parse(lang: Lang, source: &str) -> Result<ParsedFile, crate::SurveyError> {
151	    let queries = &QUERIES[&lang];
152	    let mut parser = Parser::new();
153	    parser
154	        .set_language(&queries.language)
155	        .map_err(|e| crate::SurveyError::Internal(format!("set_language failed: {e}")))?;
156	    let tree = parser.parse(source, None).ok_or_else(|| {
157	        crate::SurveyError::Internal("tree-sitter parse returned None".to_owned())
158	    })?;
159	    let root = tree.root_node();
160	
161	    let symbols = extract_symbols(&queries.symbols, root, source);
162	    let refs = extract_refs(&queries.refs, root, source);
163	    Ok(ParsedFile { symbols, refs })
164	}
165	
166	fn extract_symbols(query: &Query, root: Node, source: &str) -> Vec<ParsedSymbol> {
167	    let names = query.capture_names();
168	    let mut cursor = QueryCursor::new();
169	    let mut out = Vec::new();
170	    let mut matches = cursor.matches(query, root, source.as_bytes());
171	    while let Some(m) = matches.next() {
172	        let mut def_node: Option<(Node, SymbolKind)> = None;
173	        let mut name: Option<String> = None;
174	        for cap in m.captures {
175	            let cap_name = names[cap.index as usize];
176	            if cap_name == "name" {
177	                name = cap
178	                    .node
179	                    .utf8_text(source.as_bytes())
180	                    .ok()
181	                    .map(str::to_owned);
182	            } else if let Some(kind) = kind_from_capture(cap_name) {
183	                def_node = Some((cap.node, kind));
184	            }
185	        }
186	        if let (Some((node, kind)), Some(name)) = (def_node, name) {
187	            out.push(ParsedSymbol {
188	                name,
189	                kind,
190	                start_line: node.start_position().row as u32 + 1,
191	                end_line: node.end_position().row as u32 + 1,
192	                signature: signature_of(node, source),
193	            });
194	        }
195	    }
196	    out
197	}
198	
199	fn extract_refs(query: &Query, root: Node, source: &str) -> Vec<ParsedRef> {
200	    let names = query.capture_names();
201	    let mut cursor = QueryCursor::new();
202	    let mut out = Vec::new();
203	    let mut matches = cursor.matches(query, root, source.as_bytes());
204	    while let Some(m) = matches.next() {
205	        for cap in m.captures {
206	            let kind = match names[cap.index as usize] {
207	                "call" => RefKind::Call,
208	                "reference" => RefKind::Reference,
209	                _ => continue,
210	            };
211	            if let Ok(text) = cap.node.utf8_text(source.as_bytes()) {
212	                out.push(ParsedRef {
213	                    dst_name: text.to_owned(),
214	                    kind,
215	                    line: cap.node.start_position().row as u32 + 1,
216	                });
217	            }
218	        }
219	    }
220	    out
221	}
222	
223	/// Attribute each reference to the innermost symbol whose line span contains
224	/// it, returning `(src_symbol_index, ref)` pairs. References that fall outside
225	/// every symbol are dropped.
226	pub(crate) fn attribute_refs<'a>(
227	    symbols: &[ParsedSymbol],
228	    refs: &'a [ParsedRef],
229	) -> Vec<(usize, &'a ParsedRef)> {
230	    refs.iter()
231	        .filter_map(|r| {
232	            symbols
233	                .iter()
234	                .enumerate()
235	                .filter(|(_, s)| s.start_line <= r.line && r.line <= s.end_line)
236	                .min_by_key(|(_, s)| s.end_line - s.start_line)
237	                .map(|(idx, _)| (idx, r))
238	        })
239	        .collect()
240	}
241	
242	#[cfg(test)]
243	mod tests {
244	    use super::*;
245	
246	    #[test]
247	    fn rust_extracts_functions_and_calls() {
248	        let src = "fn helper() {}\nfn caller() {\n    helper();\n}\n";
249	        let parsed = parse(Lang::Rust, src).unwrap();
250	        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
251	        assert!(names.contains(&"helper"));
252	        assert!(names.contains(&"caller"));
253	        assert!(parsed.refs.iter().any(|r| r.dst_name == "helper"));
254	
255	        let attributed = attribute_refs(&parsed.symbols, &parsed.refs);
256	        let caller_idx = parsed
257	            .symbols
258	            .iter()
259	            .position(|s| s.name == "caller")
260	            .unwrap();
261	        assert!(attributed
262	            .iter()
263	            .any(|(idx, r)| *idx == caller_idx && r.dst_name == "helper"));
264	    }
265	
266	    #[test]
267	    fn python_extracts_classes_and_functions() {
268	        let src = "class Foo:\n    def method(self):\n        bar()\n\ndef bar():\n    pass\n";
269	        let parsed = parse(Lang::Python, src).unwrap();
270	        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
271	        assert!(names.contains(&"Foo"));
272	        assert!(names.contains(&"method"));
273	        assert!(names.contains(&"bar"));
274	        assert!(parsed.refs.iter().any(|r| r.dst_name == "bar"));
275	    }
276	
277	    #[test]
278	    fn go_extracts_funcs_and_types() {
279	        let src = "package main\ntype T struct{}\nfunc f() {\n\tg()\n}\nfunc g() {}\n";
280	        let parsed = parse(Lang::Go, src).unwrap();
281	        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
282	        assert!(names.contains(&"T"));
283	        assert!(names.contains(&"f"));
284	        assert!(names.contains(&"g"));
285	        assert!(parsed.refs.iter().any(|r| r.dst_name == "g"));
286	    }
287	
288	    #[test]
289	    fn typescript_extracts_interface_and_class() {
290	        let src = "interface I { x: number }\nclass C {\n  m() { fn(); }\n}\nfunction fn() {}\n";
291	        let parsed = parse(Lang::TypeScript, src).unwrap();
292	        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
293	        assert!(names.contains(&"I"));
294	        assert!(names.contains(&"C"));
295	        assert!(names.contains(&"fn"));
296	        assert!(parsed.refs.iter().any(|r| r.dst_name == "fn"));
297	    }
298	
299	    #[test]
300	    fn javascript_extracts_arrow_and_calls() {
301	        let src = "const add = (a, b) => a + b;\nfunction run() {\n  add(1, 2);\n}\n";
302	        let parsed = parse(Lang::JavaScript, src).unwrap();
303	        let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
304	        assert!(names.contains(&"add"));
305	        assert!(names.contains(&"run"));
306	        assert!(parsed.refs.iter().any(|r| r.dst_name == "add"));
307	    }
308	}
