 let names: Vec<&str> = parsed.symbols.iter().map(|s| s.name.as_str()).collect();
 assert!(names.contains(&"Foo"));
 assert!(names.contains(&"method"));
 assert!(names.contains(&"bar"));
 assert!(parsed.refs.iter().any(|r| r.dst_name == "bar"));
 }

