116	    /// Serialize a result to JSON, prefixing a staleness banner only when the
117	    /// watcher has flagged the index dirty (so the common path stays cheap).
118	    async fn respond<T: serde::Serialize>(&self, value: &T) -> Result<CallToolResult, McpError> {
119	        let mut contents = Vec::new();
120	        if self.dirty.load(Ordering::Relaxed) {
121	            if let Ok(status) = self.survey.status().await {
122	                if !status.pending.is_empty() {
123	                    let sample: Vec<&str> = status
124	                        .pending
125	                        .iter()
126	                        .take(10)
127	                        .map(|p| p.path.as_str())
128	                        .collect();
129	                    contents.push(Content::text(format!(
130	                        "STALE: {} file(s) differ from the index (e.g. {}). \
131	                         A rebuild is in progress; Read these files directly if you need current contents.",
132	                        status.pending.len(),
133	                        sample.join(", ")
134	                    )));
135	                }
136	            }
137	        }
138	        let json = serde_json::to_string_pretty(value)
139	            .map_err(|e| McpError::internal_error(e.to_string(), None))?;
140	        contents.push(Content::text(json));
141	        Ok(CallToolResult::success(contents))
142	    }
143	}
