166	/// Run the MCP server over stdio until the client disconnects.
167	///
168	/// Performs a connect-time incremental build (freshness layer 3), spawns the
169	/// debounced watcher (layer 1), then serves the four tools.
170	pub async fn serve_stdio(survey: Survey) -> Result<(), SurveyError> {
171	    // Layer 3: reconcile the index with the tree before answering anything.
172	    survey.build(BuildOptions::default()).await?;
173	
174	    // Layer 1: background watcher keeps the index fresh and flips the dirty flag.
175	    let dirty = Arc::new(AtomicBool::new(false));
176	    tokio::spawn(watch_task(survey.clone(), Arc::clone(&dirty)));
177	
178	    let server = SurveyServer::new(survey, dirty);
179	    let running = server
180	        .serve(stdio())
181	        .await
182	        .map_err(|e| SurveyError::Internal(format!("mcp serve failed: {e}")))?;
183	    running
184	        .waiting()
185	        .await
186	        .map_err(SurveyError::Join)
187	        .map(|_| ())
188	}
