1	//! Debounced filesystem watcher (freshness layer 1): on any change under the
2	//! repo root, mark the index dirty and trigger an incremental rebuild after a
3	//! short quiet period. The `dirty` flag lets the MCP layer surface a staleness
4	//! banner cheaply without re-hashing the tree on every query.
5	
6	use std::sync::atomic::{AtomicBool, Ordering};
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	use notify::{RecursiveMode, Watcher};
11	use tokio::sync::mpsc;
12	
13	use crate::model::BuildOptions;
14	use crate::{Survey, SurveyError};
15	
16	const DEBOUNCE: Duration = Duration::from_millis(500);
17	
18	/// Watch the repo and rebuild the index after each burst of changes. Runs
19	/// until the watcher channel closes. `dirty` is set when changes arrive and
20	/// cleared after a successful rebuild.
21	pub(crate) async fn watch_loop(survey: Survey, dirty: Arc<AtomicBool>) -> Result<(), SurveyError> {
22	    let (tx, mut rx) = mpsc::unbounded_channel();
23	    let mut watcher = notify::recommended_watcher(move |res: notify::Result<notify::Event>| {
24	        if let Ok(event) = res {
25	            // Ignore events that touch only pruned trees — most importantly the
26	            // index's own `.derrick/index.db` writes, which would otherwise
27	            // re-arm the watcher after every rebuild and loop forever. An event
28	            // with no paths is treated as relevant (safe default).
29	            let relevant = event.paths.is_empty()
30	                || event
31	                    .paths
32	                    .iter()
33	                    .any(|p| !crate::walk::is_under_skipped_dir(p));
34	            if relevant {
35	                let _ = tx.send(());
36	            }
37	        }
38	    })?;
39	    watcher.watch(survey.repo_root(), RecursiveMode::Recursive)?;
40	
41	    while rx.recv().await.is_some() {
42	        dirty.store(true, Ordering::Relaxed);
43	        // Drain the burst: keep resetting the timer until things go quiet.
44	        loop {
45	            tokio::select! {
46	                () = tokio::time::sleep(DEBOUNCE) => break,
47	                msg = rx.recv() => {
48	                    if msg.is_none() {
49	                        return Ok(());
50	                    }
51	                }
52	            }
53	        }
54	        if let Err(error) = survey.build(BuildOptions::default()).await {
55	            tracing::warn!(%error, "survey watch rebuild failed");
56	        } else {
57	            dirty.store(false, Ordering::Relaxed);
58	        }
59	    }
60	    Ok(())
61	}
