84	        let dirty = Arc::new(AtomicBool::new(false));
85	        let watcher = tokio::spawn(watch_loop(survey.clone(), Arc::clone(&dirty)));
86	
87	        // Give the watcher a moment to arm its event stream.
88	        tokio::time::sleep(Duration::from_millis(500)).await;
89	
90	        // Poll until the debounced rebuild surfaces the new symbol. The event
91	        // stream can take a variable time to arm (FSEvents on macOS in
92	        // particular), so re-touch the file each iteration to keep generating
93	        // events until one is caught, and allow a generous deadline.
94	        let added = repo.join("added.rs");
95	        let deadline = Instant::now() + Duration::from_secs(20);
96	        let mut found = false;
