99	            // Wait longer than the debounce window so the burst goes quiet and
100	            // the rebuild actually fires before the next touch re-arms it.
101	            tokio::time::sleep(DEBOUNCE + Duration::from_millis(500)).await;
102	            let hits = survey.search("brand_new_symbol", 5).await?;
103	            if hits.iter().any(|h| h.name == "brand_new_symbol") {
104	                found = true;
